import { createContext, useContext, useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import { KeyRound } from "lucide-react";

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState(null);
  const location = useLocation();

  useEffect(() => {
    const validateToken = async (retry = false) => {
      const token = localStorage.getItem("authToken");
      const user_id = localStorage.getItem("user_id");
      const username = localStorage.getItem("username");
      const role = localStorage.getItem("role");

      if (!token) {
        setIsAuthenticated(false);
        setUser(null);
        setLoading(false);
        return;
      }

      try {
        const response = await fetch("http://localhost:5000/api/validate", {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (response.ok) {
          setIsAuthenticated(true);
          setUser({ id: user_id, username, role });
        } else {
          if (!retry) {
            console.warn("Validation failed, retrying...");
            return validateToken(true);
          }
          localStorage.clear();
          setIsAuthenticated(false);
          setUser(null);
        }
      } catch (error) {
        console.error("Token validation error:", error);
        if (!retry) {
          console.warn("Retrying after error...");
          return validateToken(true);
        }
        localStorage.clear();
        setIsAuthenticated(false);
        setUser(null);
      } finally {
        setLoading(false);
      }
    };

    const timer = setTimeout(() => {
      validateToken();
    }, 100);

    return () => clearTimeout(timer);
  }, []);

  const login = async (username, password) => {
    try {
      const response = await fetch("http://localhost:5000/api/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username, password }),
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("authToken", data.token);
        localStorage.setItem("username", data.username);
        localStorage.setItem("user_id", data.user_id);
        localStorage.setItem("role", data.role);
        localStorage.setItem("isAdmin", data.role === "admin" ? "true" : "false");

        setIsAuthenticated(true);
        setUser({
          id: data.user_id,
          username: data.username,
          role: data.role,
        });

        return true;
      } else {
        console.error("Login failed:", data.error);
        return false;
      }
    } catch (error) {
      console.error("Error logging in:", error);
      return false;
    }
  };

  const logout = () => {
    localStorage.clear();
    setIsAuthenticated(false);
    setUser(null);
  };

  const protectedRoutes = [
    "/dashboard",
    "/roster",
    "/shift_handover",
    "/knowledge_base",
    "/operation_runbook",
    "/advisory_system"
  ];

  if (loading && protectedRoutes.includes(location.pathname)) {
    return (
      <div style={{
        width: "100vw",
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        textAlign: "center"
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <KeyRound />
          <span>Authenticating User...</span>
        </div>
      </div>
    );
  }

  return (
    <AuthContext.Provider value={{ isAuthenticated, login, logout, user }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
